  sel=list(comb)
  # Check requires closure
  valid_requires=True
  sel_set=set(sel)
  for o in opts:
   if o['id'] in sel_set:
    for r in o['requires']:
     if r not in sel_set:
      valid_requires=False
      break
   if not valid_requires:
    break
  if not valid_requires:
   continue
  # Check cover tags
  tags_covered=[]
  for o in opts:
   if o['id'] in sel_set:
    tags_covered+=o['tags']
  tags_covered_set=set(tags_covered)
  cover_tags=goal['cover'].get('tags',[])
  if not all(t in tags_covered_set for t in cover_tags):
   continue
  # Check sum_bounds cost max
  total_cost=0
  for o in opts:
   if o['id'] in sel_set:
    total_cost+=o.get('cost',0)
  if 'cost' in goal['sum_bounds']:
   if 'max' in goal['sum_bounds']['cost']:
    if total_cost>goal['sum_bounds']['cost']['max']:
     continue
  # no_conflicts false means conflicts allowed
  # unique empty means no uniqueness constraints
  # order_by empty means no ordering constraints
  # Check valid
  if valid(sel):
   result=sel
   break
